//! Quest ID -> display metadata extracted from MHGU Database's `quests` table.
//!
//! The JSON is generated by `tools/extract_mhgudb_quests.py`; only the names, goals,
//! rank/hub and star count are kept, never the source APK or the full database.

use serde_json::Value;
use std::collections::HashMap;
use std::sync::OnceLock;

pub struct QuestInfo {
    pub name: String,
    pub name_es: String,
    pub name_zh: String,
    pub goal: String,
    pub goal_es: String,
    pub goal_zh: String,
    pub rank: String,
    pub stars: u8,
}

fn text(v: &Value, key: &str) -> String {
    v.get(key).and_then(Value::as_str).unwrap_or("").to_string()
}

fn load() -> HashMap<u32, QuestInfo> {
    let mut out = HashMap::new();
    let Some(quests) = serde_json::from_str::<Value>(include_str!("../data/quests.json"))
        .ok()
        .and_then(|v| v.get("quests").cloned())
        .and_then(|v| v.as_object().cloned())
    else {
        return out;
    };
    for (id, v) in quests {
        let Ok(id) = id.parse::<u32>() else { continue };
        out.insert(
            id,
            QuestInfo {
                name: text(&v, "name"),
                name_es: text(&v, "name_es"),
                name_zh: text(&v, "name_zh"),
                goal: text(&v, "goal"),
                goal_es: text(&v, "goal_es"),
                goal_zh: text(&v, "goal_zh"),
                rank: text(&v, "rank"),
                stars: v.get("stars").and_then(Value::as_u64).unwrap_or(0).min(255) as u8,
            },
        );
    }
    out
}

pub fn get(id: u32) -> Option<&'static QuestInfo> {
    static QUESTS: OnceLock<HashMap<u32, QuestInfo>> = OnceLock::new();
    QUESTS.get_or_init(load).get(&id)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn known_quest_maps_to_its_name() {
        let q = get(10216).expect("quest 10216");
        assert_eq!(q.name, "The New Tenant");
        assert_eq!(q.name_zh, "雪山之主――雪狮子王");
        assert_eq!(q.goal, "Hunt a Blangonga");
        assert_eq!(q.goal_zh, "狩猎1头雪狮子王");
        assert_eq!(q.rank, "LR");
        assert_eq!(q.stars, 2);
    }
}
